package ai.eva.android.probe;
import android.app.Instrumentation;import android.os.Bundle;import android.net.Uri;import android.webkit.WebResourceResponse;import java.io.File;import java.nio.file.Files;import java.util.UUID;
public final class ExtensionMediaCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=0;File dir=null;try{String logical="/root/eva-workspace/.eva-logo-check-"+UUID.randomUUID();dir=ExtensionAuthoring.hostFile(getTargetContext(),logical);dir.mkdirs();File svg=new File(dir,"logo.svg");Files.write(svg.toPath(),"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\"><rect width=\"24\" height=\"24\" fill=\"blue\"/></svg>".getBytes("UTF-8"));WebResourceResponse ok=ExtensionAuthoring.media(getTargetContext(),Uri.parse("https://eva.invalid/extension-media?path="+Uri.encode(logical+"/logo.svg")));if(ok.getStatusCode()!=200||!"image/svg+xml".equals(ok.getMimeType())||!ok.getResponseHeaders().get("Content-Security-Policy").contains("sandbox"))throw new Exception("SVG image boundary");ok.getData().close();for(String bad:new String[]{"/root/.eva-codex/auth.json",logical+"/../../.eva-codex/auth.json"})if(ExtensionAuthoring.media(getTargetContext(),Uri.parse("https://eva.invalid/extension-media?path="+Uri.encode(bad))).getStatusCode()!=404)throw new Exception("path boundary");Files.createSymbolicLink(new File(dir,"link.svg").toPath(),svg.toPath());if(ExtensionAuthoring.media(getTargetContext(),Uri.parse("https://eva.invalid/extension-media?path="+Uri.encode(logical+"/link.svg"))).getStatusCode()!=404)throw new Exception("symlink boundary");result.putString("result","PASS local SVG image serving + sandbox headers; credential/traversal/symlink reads rejected");}catch(Exception e){code=1;result.putString("error",e.toString());}finally{try{if(dir!=null&&dir.exists())SkillStore.remove(dir,dir.getCanonicalPath());}catch(Exception e){code=1;result.putString("cleanupError",e.toString());}}finish(code,result);}
}
